#include "field.hpp"
#include <tuple>
#include <map>
using Clock=std::chrono::steady_clock;
struct Linear{int n,rank=0;std::array<U,128>v{};std::array<uint64_t,128>r{};std::vector<uint64_t>kernel;std::vector<U>cols;
 Linear(int nn,const std::vector<U>&c,bool track=false):n(nn),cols(c){assert(!track||c.size()<64);for(size_t j=0;j<c.size();j++){U x=c[j];uint64_t rep=track?(uint64_t(1)<<j):0;while(x){int i=degree(x);if(v[i]){x^=v[i];rep^=r[i];}else{v[i]=x;r[i]=rep;rank++;break;}}if(!x&&track)kernel.push_back(rep);}}
 std::pair<U,uint64_t> reduce(U x)const{uint64_t rep=0;for(int i=n-1;i>=0;i--)if(((x>>i)&1)&&v[i]){x^=v[i];rep^=r[i];}return{x,rep};}
 U certificate(U rhs)const{U rem=reduce(rhs).first;if(!rem)return 0;int k=degree(rem);U lam=0;for(int i=0;i<n;i++)if((reduce(U(1)<<i).first>>k)&1)lam|=U(1)<<i;for(U c:cols)assert(!par(lam&c));assert(par(lam&rhs));return lam;}
 static bool par(U x){return (__builtin_popcountll(uint64_t(x))^__builtin_popcountll(uint64_t(x>>64)))&1;}
};
struct Cell{std::vector<U>cols;U rhs;};
Cell relaxed(const F&f,int d,U s,const std::vector<U>&vs){Cell c;c.rhs=1;for(int j=0;j<2*d-1;j++)c.cols.push_back(f.sq(U(1)<<j)^f.mul(s,U(1)<<j));for(int i=0;i<d;i++)c.cols.push_back(f.mul(f.sq(s),f.sq(U(1)<<i)));for(U v:vs){for(int j=0;j<2*d-1;j++)c.cols.push_back(f.mul(v,U(1)<<j));for(int i=0;i<d;i++)c.cols.push_back(f.mul(f.sq(v),f.sq(U(1)<<i)));}return c;}
Cell fixed_sum(const F&f,int d,U p,U s,const std::vector<U>&vs){Cell c;U p2=f.sq(p);c.rhs=f.mul(f.sq(s),p2)^1;std::vector<U>q;for(int i=0;i<d;i++){U t=U(1)<<i;U qi=f.sq(t)^f.mul(p,t);q.push_back(qi);c.cols.push_back(f.sq(qi)^f.mul(s,qi));}for(U v:vs){for(U qi:q)c.cols.push_back(f.mul(v,qi));c.cols.push_back(f.mul(f.sq(v),p2));}return c;}
std::set<uint64_t> point(const F&f,int d,U p,U s){auto c=fixed_sum(f,d,p,s,{});Linear m(f.n,c.cols,true);auto reduced=m.reduce(c.rhs);std::set<uint64_t>xs;if(reduced.first)return xs;assert(m.kernel.size()<=2);for(unsigned t=0;t<(1u<<m.kernel.size());t++){uint64_t x=reduced.second;for(size_t i=0;i<m.kernel.size();i++)if(t>>i&1)x^=m.kernel[i];assert(x<(uint64_t(1)<<d));assert(f.s3(x,U(x)^p,s)==0);xs.insert(x);}return xs;}
U oracle_mul(U a,U b,int n,U mod){U raw=0;for(int i=0;i<n;i++)if((b>>i)&1)raw^=a<<i;for(int i=2*n-2;i>=n;i--)if((raw>>i)&1)raw^=mod<<(i-n);return raw;}
U oracle_s3(U x,U y,U s,int n,U mod){auto mul=[&](U a,U b){return oracle_mul(a,b,n,mod);};U a=mul(x,y),b=mul(x,s),c=mul(y,s);return mul(a,a)^mul(b,b)^mul(c,c)^mul(a,s)^1;}
std::vector<U>expand(U base,const std::vector<U>&vs){assert(vs.size()<=8);std::vector<U>r;for(size_t m=0;m<(size_t(1)<<vs.size());m++){U x=base;for(size_t i=0;i<vs.size();i++)if(m>>i&1)x^=vs[i];r.push_back(x);}return r;}
struct Odd{int p,degree,q;int add(int x,int y)const{return degree==1?(x+y)%p:(x%p+y%p)%p+p*((x/p+y/p)%p);}int neg(int x)const{return degree==1?(p-x)%p:(p-x%p)%p+p*((p-x/p)%p);}int sub(int x,int y)const{return add(x,neg(y));}int mul(int x,int y)const{if(degree==1)return x*y%p;return ((x%p*(y%p)-x/p*(y/p))%p+p)%p+p*((x%p*(y/p)+x/p*(y%p))%p);}int sc(int n)const{return n%p;}int sq(int x)const{return mul(x,x);} };
int os3(const Odd&f,int x,int y,int z,int a,int b){int xy=f.mul(x,y),p=f.add(x,y);return f.sub(f.add(f.mul(f.sq(f.sub(x,y)),f.sq(z)),f.sq(f.sub(xy,a))),f.add(f.mul(f.sc(2),f.mul(f.add(f.mul(p,f.add(xy,a)),f.mul(f.sc(2),b)),z)),f.mul(f.sc(4),f.mul(b,p))));}
int chart(const Odd&f,int p,int q,int s,int a,int b){int u=f.mul(f.sub(f.sq(p),f.mul(f.sc(4),q)),f.sq(s));int v=f.mul(f.sc(2),f.mul(f.add(f.mul(p,f.add(q,a)),f.mul(f.sc(2),b)),s));return f.sub(f.add(u,f.sq(f.sub(q,a))),f.add(v,f.mul(f.sc(4),f.mul(b,p))));}
std::pair<size_t,size_t>odd_controls(){size_t identities=0,roots=0;for(Odd f:std::vector<Odd>{{3,1,3},{5,1,5},{7,1,7},{11,1,11},{3,2,9}}){int a=1,b=1;assert(f.add(f.sq(1),f.sq(1))!=f.sq(f.add(1,1)));std::vector<int>D=f.degree==1?std::vector<int>{0,1,2}:std::vector<int>{0,1,3};std::set<std::tuple<int,int,int>>lhs,rhs;for(int s=0;s<f.q;s++){for(int x=0;x<f.q;x++)for(int y=0;y<f.q;y++){assert(os3(f,x,y,s,a,b)==chart(f,f.add(x,y),f.mul(x,y),s,a,b));identities++;}for(int x:D)for(int y:D)if(!os3(f,x,y,s,a,b))lhs.emplace(s,x,y);for(int p=0;p<f.q;p++)for(int q=0;q<f.q;q++)if(!chart(f,p,q,s,a,b))for(int x:D){int y=f.sub(p,x);if(std::find(D.begin(),D.end(),y)!=D.end()&&f.add(f.sub(f.sq(x),f.mul(p,x)),q)==0)rhs.emplace(s,x,y);}}assert(lhs==rhs);roots+=lhs.size();}return{identities,roots};}
void controls(const std::string&id){size_t points=0,cells=0,certs=0,pairs=0;for(auto cfg:std::vector<std::tuple<int,U,int>>{{2,7,1},{3,11,2},{4,19,2},{4,31,2},{5,37,3},{7,131,3}}){auto[n,mod,d]=cfg;F f(n,mod);assert(f.irreducible());int N=1<<n,D=1<<d;std::vector<std::set<uint64_t>>oracle(D*N);for(int p=0;p<D;p++)for(int s=0;s<N;s++){for(int x=0;x<D;x++)if(!oracle_s3(x,x^p,s,n,mod)){oracle[p*N+s].insert(x);pairs++;}assert(point(f,d,p,s)==oracle[p*N+s]);points++;auto c=relaxed(f,d,s,{});Linear m(n,c.cols);U lam=m.certificate(1);if(lam){for(int pp=0;pp<D;pp++)assert(oracle[pp*N+s].empty());}}
 for(int s=0;s<N;s++)for(auto vs:std::vector<std::vector<U>>{{},{1},{2},{2,4}}){if(vs.size()==2&&n<3)continue;auto members=expand(s,vs);auto r=relaxed(f,d,s,vs);Linear rm(n,r.cols);U rl=rm.certificate(1);if(std::find(vs.begin(),vs.end(),U(1))!=vs.end())assert(!rl);if(rl){certs++;for(U ss:members)for(int p=0;p<D;p++)assert(oracle[p*N+unsigned(ss)].empty());}cells++;for(int p=0;p<D;p++){auto c=fixed_sum(f,d,p,s,vs);Linear m(n,c.cols);U lam=m.certificate(c.rhs);if(lam){certs++;for(U ss:members)assert(oracle[p*N+unsigned(ss)].empty());}if(vs.empty())assert(bool(lam)==oracle[p*N+s].empty());cells++;}}
 }auto oi=odd_controls();std::cout<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<id<<"\",\"status\":\"passed\",\"summary\":\"Independent exhaustive pair roots validate point recovery and uniform dual cells; odd pair chart matches literal S3.\",\"evidence\":{\"binary_point_comparisons\":"<<points<<",\"binary_cell_comparisons\":"<<cells<<",\"certificates_checked\":"<<certs<<",\"ordered_pair_roots\":"<<pairs<<",\"odd_identity_checks\":"<<oi.first<<",\"odd_chart_ordered_roots\":"<<oi.second<<",\"odd_fields\":[3,5,7,11,9],\"original_hard_root_count_exact\":null,\"release_gate_claim\":false},\"next_actions\":[\"Profile fixed preregistered actual-field cofactor directions; certificates are sufficient, and failed common certificates are inconclusive.\"]}\n";}
std::vector<U>directions(int family,int k){std::vector<U>v;for(int i=0;i<k;i++)v.push_back(U(1)<<(family==0?i:family==1?i+1:65+i));return v;}
void profile(const std::string&id,bool fixed){F f(83,hex("800000000200000000007"));assert(f.irreducible());int d=18;U target=hex("622425e96ba633969263b"),mask=(U(1)<<83)-1;std::vector<U>centers{0,1,target,f.inv(target)};uint64_t state=0x71933abcd5781ULL;for(int i=0;i<12;i++){state^=state<<13;state^=state>>7;state^=state<<17;U s=U(state)<<19;state^=state<<13;state^=state>>7;state^=state<<17;s^=state;centers.push_back(s&mask);}for(U pp:std::vector<U>{2,3,0x12345,0x3ffff})centers.push_back(f.inv(pp));std::set<std::string>all_pairs;std::vector<U>ps=fixed?std::vector<U>{0,1,2,3,0x12345,0x3ffff}:std::vector<U>{0};size_t tested=0,certified=0,positive_dim_certified=0,point_checks=0,verified_roots=0,rankmin=83,rankmax=0,covered_parameter_volume=0;std::ostringstream cases;bool first=true;
 for(U p:ps)for(int family=0;family<3;family++)for(int k:std::vector<int>{0,1,2,4,8})for(size_t ci=0;ci<centers.size();ci++){auto vs=directions(family,k);U base=centers[ci];auto c=fixed?fixed_sum(f,d,p,base,vs):relaxed(f,d,base,vs);Linear m(83,c.cols);U lam=m.certificate(c.rhs);rankmin=std::min(rankmin,size_t(m.rank));rankmax=std::max(rankmax,size_t(m.rank));tested++;if(lam){certified++;if(k>0){positive_dim_certified++;}covered_parameter_volume+=size_t(1)<<k;}if(!fixed&&family==0&&k>0)assert(!lam);
 if(fixed){for(U s:expand(base,vs)){auto xs=point(f,d,p,s);point_checks++;if(lam)assert(xs.empty());verified_roots+=xs.size();for(uint64_t x:xs)all_pairs.insert(hx(x)+":"+hx(U(x)^p)+":"+hx(s));}}
 if(!first){cases<<",";}first=false;cases<<"{\"p\":\""<<hx(p)<<"\",\"family\":"<<family<<",\"dimension\":"<<k<<",\"center\":\""<<hx(base)<<"\",\"rank\":"<<m.rank<<",\"certificate\":\""<<hx(lam)<<"\"}";
 }
 std::ostringstream pair_json;bool pair_first=true;for(const auto& root:all_pairs){if(!pair_first){pair_json<<",";}pair_first=false;pair_json<<"\""<<root<<"\"";}
 std::cout<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<id<<"\",\"status\":\""<<(positive_dim_certified?"passed":"refuted")<<"\",\"summary\":\""<<(fixed?"Fixed-sum exact pair-fiber cells":"Unconditioned relaxed pair-fiber cells")<<" profiled with checked dual certificates; not a full hard solve.\",\"evidence\":{\"fixed_pair_sum\":"<<(fixed?"true":"false")<<",\"cells_tested\":"<<tested<<",\"cells_certified_empty\":"<<certified<<",\"positive_dimension_cells_certified_empty\":"<<positive_dim_certified<<",\"rank_min\":"<<rankmin<<",\"rank_max\":"<<rankmax<<",\"point_fibers_verified\":"<<point_checks<<",\"sum_verified_pair_root_counts\":"<<verified_roots<<",\"sum_certified_parameter_volume_not_union\":"<<covered_parameter_volume<<",\"cases\":["<<cases.str()<<"],\"verified_component_pair_tuples\":["<<pair_json.str()<<"],\"pair_corpus_complete\":"<<(fixed?"true":"false")<<",\"original_hard_root_count_exact\":null,\"qualified_speedup\":null,\"release_gate_claim\":false},\"next_actions\":[\"Do not add overlapping cofactor volumes or extrapolate sampled coverage; outer pair-sum and auxiliary cells remain unpaid.\",\"If unconditioned cells fail, condition the pair sum and use exact source-linear recovery, retaining p0 repeats.\",\"If conditional cells help, quantify full outer coverage and integrate a sound partial-state certificate controller before any new hard search.\"]}\n";
}
int main(int argc,char**argv){try{assert(argc==3);auto t=Clock::now();std::ostringstream capture;auto*old=std::cout.rdbuf(capture.rdbuf());if(std::string(argv[2])=="controls")controls(argv[1]);else profile(argv[1],std::string(argv[2])=="fixed");std::cout.rdbuf(old);std::string out=capture.str();if(std::chrono::duration<double>(Clock::now()-t).count()>=65.){std::cout<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<argv[1]<<"\",\"status\":\"inconclusive\",\"summary\":\"Result exceeded serialization boundary.\",\"evidence\":{\"original_hard_root_count_exact\":null},\"next_actions\":[\"Change bounded profile or storage before retry.\"]}\n";}else std::cout<<out;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
